def paras(w,*texts):
 for text in texts:w.p(text)

def sub(w,title,*texts):w.h(title);paras(w,*texts)

def write_problem(w,table):
 w.page('1 Вербальное описание предметной области',1)
 sub(w,'1.1 Характеристика деятельности и участники',
 'Банк обслуживает физических лиц через отделения. Сотрудники ведут сведения о клиентах и счетах, оформляют карты, исполняют внутрибанковские переводы и регистрируют утверждённые кредитные договоры. Обращение завершается документом для клиента и соответствующим состоянием учёта. Основание операции, реквизиты, суммы, даты и автор должны быть доступны для последующей проверки.',
 'Клиент предоставляет распоряжение и согласует условия обслуживания. Оператор проверяет основания и выполняет операции со счетами, картами и переводами. Кредитный специалист оформляет договор и его план, контролёр проверяет сведения и историю, администратор ведёт доступ и справочники. Руководитель определяет регламент обслуживания, допустимый расход ресурсов и условия приёмки системы.',
 'Рассматриваемый контур работает с рублёвыми счетами одного банка. Межбанковские расчёты и операции внешних карточных сетей относятся к смежным системам. Решение о выдаче кредита и подтверждение фактического погашения предоставляет кредитная служба; в данном контуре учитываются утверждённые условия и план.')
 sub(w,'1.2 Проблема и интерес заказчика',
 'Заказчиком и лицом, принимающим решение о приёмке, выступает '+OWNER+'. Ему необходимо завершать обращения своевременно и правильно при заданном составе сотрудников. Результат должен быть пригоден для выдачи клиенту и последующего контроля обязательств банка.',
 BUSINESS_PROBLEM,
 'Повторный ввод реквизитов и ручное согласование связанных записей увеличивают трудозатраты на обслуживание. Ускорение одного действия может перенести затраты на исправления и сверку. Поэтому при оценке результата учитывается полный цикл от предъявления основания до выдачи верного документа и проверки учёта.')
 table(w,'Варианты организации контроля и обслуживания',['Вариант','Возможность','Цена и ограничение'],ALTERNATIVES,[38,53,74])
 sub(w,'1.3 Назначение системы и программного продукта',
 'Назначение системы — обеспечивать подтверждённое завершение обращений физических лиц с согласованным учётом и сокращением удельного ручного труда при неизменном составе исполнителей. Основной результат деятельности — правильно оформленное обращение. Подтверждения, выписки, графики, журнал изменений и сводки обеспечивают его получение и контроль.',
 'Система объединяет исполнителей, регламент и информационные средства. Поставляемый программный продукт реализует операции ведения данных, проверки, расчёта и подготовки документов. Его состав и показатели определяются назначением и условиями применения [13, 14].')
 table(w,'Деятельность, система и программный продукт',['Объект','Назначение и граница'],EXTERNAL,[39,126])
 paras(w,HYPOTHESIS,
 'Для проверки Г0 сопоставляются два способа выполнения одинаковых обращений: ручной порядок А и процесс Б с программной поддержкой. Критерии охватывают правильность документов, согласованность учёта, время обслуживания и труд всех участвующих сотрудников. Частные гипотезы и обеспечивающие их функции раскрыты в разделе 3.')
 sub(w,'1.4 Концепция качества и достижение назначения',
 'Качество определяется степенью соответствия собственных характеристик результата установленным требованиям [8]. Руководителю необходимы правильное завершение обслуживания и допустимый расход труда; клиенту — верный документ; контролёру — возможность восстановить основания и изменения. Эти интересы выражены критериями ЦП1–ЦП4.',
 'Число правильно завершённых обращений обозначается Q, суммарный труд сотрудников — L, удельный труд — u=L/Q. Для оперативности измеряется длительность обращения, для сохранности — число критических нарушений. Свидетельства связывают задание, документ, состояние учёта и фактические затраты. Внешнее назначение и порядок оценки показаны на рисунках Г.4–Г.5, понятия качества — на А.3.')
 table(w,'Критерии достижения назначения',['Код','Свойство','Измерение','Проектная норма'],GOALS,[13,31,60,61])
 paras(w,'Нормы применяются совместно. Неверный денежный исход, несогласованный график или неразрешённое изменение исключают положительное решение независимо от экономии труда. Отсутствие необходимых наблюдений означает недостаточность свидетельств. Порядок решения установлен И25.',
 'Сравнение А/Б выполняется для тридцати сопоставимых обращений: по десять маршрутов «клиент–счёт–карта», «перевод–выписка» и «договор–график–сводка». В L включаются помощь, исправления, повторы и необходимая сверка. Данные, состав и квалификация исполнителей, регламент и критерии правильного документа фиксируются до испытаний.')
 sub(w,'1.5 Условия применения и приёмочный профиль',
 'Рабочие места находятся в защищённой сети банка; предусмотрены четыре роли и до пяти одновременных сеансов. Руководитель получает контрольные сведения в пределах полномочий контролёра. Начальные остатки и основания действующих договоров подтверждаются до запуска текущего учёта.',
 'Порог сокращения труда 20 %, состав из тридцати обращений и временные пределы являются проектными требованиями для согласования до приёмки. Их выполнение устанавливается по наблюдениям. При изменении состава обращений пересматриваются нормы и связанные проверки. Эксплуатационные показатели и финансовая оценка внедрения определяются по данным последующего применения.',
 'Испытания проводятся отдельно от рабочего контура на синтетических данных. Основной набор содержит от 1000 предметных записей, нагрузочный — 100 000 переводов. Сравнительная серия использует одинаковые исходные условия для А и Б; некорректная база А не позволяет подтвердить сокращение труда.')

def write_quality_methods(w,table):
 sub(w,'7.6 Сравнение трудозатрат полного цикла',
 'И24 проводится после положительных предметных проверок. До серии фиксируются ручной регламент А, состав сотрудников, одинаковые начальные данные и критерии конечного результата. Ручной порядок должен обеспечивать те же документы и обязательные проверки. Тридцать пар содержат допустимые задания для успешного завершения; отрицательные случаи испытываются отдельно.',
 'После тренировочных обращений выполняются измеряемые пары с чередованием А→Б и Б→А. Между независимыми случаями восстанавливается исходный набор. Наблюдатель фиксирует начало и конец, труд каждого участника, помощь, повторы, исправления и сверку. Труд разных сотрудников суммируется; одно время одного человека учитывается однократно. Работа испытателя по измерению исключается одинаково для обоих способов.',
 'Q устанавливается сравнением документа и сохранённого состояния с эталоном. Сопоставление u=L/Q допускается при Q_A=Q_B=30 и полном журнале труда. Проверяются одинаковый состав исполнителей, u_B≤0,80u_A, длительность каждого обращения Б≤120 с и отсутствие критических нарушений. Результаты дополнительно группируются по трём видам обращений.',
 'Контрольный пример расчёта формулы: при L_A=180 и L_B=135 человеко-минут, Q_A=Q_B=30 получаются u_A=6,00 и u_B=4,50 мин/обращение; сокращение составляет 25 %. Это расчётный пример, не эксплуатационный замер. Неполный журнал, нулевой знаменатель и несопоставимые условия не дают подтверждённой оценки эффекта.')
 table(w,'Журнал сравнительного испытания',['Поле','Содержание'],[
 ('Идентификация','pair_id; вид обращения; способ А/Б; порядок; версия регламента и исходного набора'),
 ('Труд','Исполнитель, роль, квалификация, интервалы; помощь, повторы и исправления'),
 ('Результат','Документ; ID предметных записей; правильность; критические нарушения'),
 ('Свидетельства','Снимок состояния, журналы, показания таймера, способ сверки и SHA-256'),
 ('Сводка','L_A, L_B, Q_A, Q_B, u_A, u_B, относительное сокращение; решение по критериям')],[38,127])
 sub(w,'7.7 Приёмка и пилотная эксплуатация',
 'Для приёмки предъявляются фиксированная сборка, документация и свидетельства. Представитель банка проверяет требования и повторяет выбранные наблюдения. По И25 он принимает решение о приёмке, исправлении или недостаточности свидетельств. Критический дефект исключает приёмку.',
 'На пилотном участке проверяется пригодность для фактической работы. План пилота определяет профиль обращений, нагрузку, участников, показатели и допустимые отклонения. Полный цикл учитывает помощь, исправления и контроль. Результаты пилота оформляются отдельно от приёмочных испытаний.')

def write_introduction(w):
 w.structural('ВВЕДЕНИЕ')
 paras(w,
 'Обслуживание физических лиц в отделениях банка требует согласованного учёта клиентов, счетов, банковских карт, переводов и кредитных договоров. Каждое обращение связано с проверкой оснований, изменением учётных данных и подготовкой документа для клиента. Ошибка в одной из связанных записей может привести к неверному остатку, повторному проведению перевода или расхождению графика платежей с условиями договора.',
 'При раздельном ведении сведений сотрудники затрачивают время на повторный ввод реквизитов и сверку результатов. Руководителю операционного направления необходимо обеспечить правильность и своевременность обслуживания при ограниченном кадровом ресурсе. Автоматизация повторяемых проверок и подготовки документов рассматривается как способ сократить ручной труд с сохранением контроля над банковскими операциями.',
 'Цель работы — спроектировать банковскую информационную систему, обеспечивающую согласованное оформление счетов, карт, внутрибанковских переводов и утверждённых кредитных договоров. Объект рассмотрения — операционное обслуживание физических лиц в отделениях банка. Предмет проектирования — данные, функции и программные средства учёта операций, формирования документов и контроля результатов.',
 'Для достижения цели определены назначение и условия применения системы, требования к результатам обслуживания, модели данных, функций и процессов. Архитектура и технический проект устанавливают ответственность компонентов, правила обработки данных и интерфейсы программных модулей. Разработанные методики предусматривают проверку корректности операций и сравнение трудозатрат на обслуживание.')

def write_project_sections(w,table,quality,principles,development,interfaces):
 w.page('2 Декларативная модель',1)
 sub(w,'2.1 Лингвистический минимум предметной области и качества',
 'Модель данных основана на содержании документов банковского обслуживания: карточке клиента, реквизитах счёта, реестре карт, распоряжении на перевод, кредитном договоре, графике платежей, выписке и журнале действий. Перечень документов ДО1–ДО10 и соответствующих им понятий приведён в приложении А.',
 'Клиент владеет счетами, счёт относится к отделению, карта обслуживает определённый счёт. Перевод связывает два счёта в ролях отправителя и получателя. Кредитный договор содержит условия и плановые платежи. Сотрудник выступает автором изменения; событие аудита связывает его действие с изменённым объектом. Эти отношения определяют смысл информации независимо от её физического хранения [16].',
 'Классификация выделяет клиентские, карточные, переводные и кредитные операции. Ассоциация связывает конкретный объект с состоянием, а сотрудника — с ролью. Агрегация объединяет связанные сведения в карточку клиента, выписку и управленческую сводку. Документы используют общие идентификаторы и реквизиты.',
 'Модель оценивания качества включает заинтересованное лицо, потребность, требование, фактор, критерий, метрику, норму, испытание, наблюдение, свидетельство и решение. На рисунке А.3 показано, как требование раскрывается критерием, наблюдаемое значение метрики сопоставляется с нормой, а свидетельство обосновывает решение о соответствии.')
 sub(w,'2.2 Концептуальная и логическая модели данных',
 'Концептуальная модель Чена представлена на рисунках А.1 и А.2. Она объединяет отделения, клиентов, счета, сотрудников, карты, переводы, кредитные договоры и плановые платежи. Для каждого отношения определены роли участников и кратности. События аудита образуют служебный ресурс контроля изменений.',
 'Логические модели А.4 и А.5 задают атрибуты отношений, типы данных, первичные и внешние ключи, уникальность и обязательность значений. Связи по внешним ключам направлены к соответствующим первичным ключам. Отношение employee хранит сведения об авторах операций и полномочиях, loan_schedule — состав договорного плана. Полный словарь атрибутов приведён в приложении И.')
 sub(w,'2.3 Нормализация и ограничения целостности',
 'Реляционная модель приведена к третьей нормальной форме. Значения атрибутов атомарны. В loan_schedule дата и суммы платежа зависят от всей пары (loan_id, payment_no). В остальных отношениях первичный ключ одноатрибутный. Владелец карты определяется через счёт; реквизиты клиента не дублируются в переводах и договорах.',
 'Поле balance хранит текущий остаток для проверки достаточности средств. Его согласованность контролируется независимым пересчётом по opening_balance и завершённым переводам. Поле transferred_at задаёт момент инициирования распоряжения, finished_at — момент его завершения или отмены. Плановые суммы договора учитываются отдельно от подтверждения фактической выдачи и погашения кредита.')
 table(w,'Предметные ограничения',['Код','Правило'],RULES,[14,151])
 paras(w,'Ключи, обязательность, уникальность и построчные условия контролируются средствами PK, FK, UNIQUE, NOT NULL и CHECK. Достаточность средств, согласованность всего графика и неизменяемость конечных фактов проверяются транзакционными операциями и отложенными ограничивающими триггерами. Межстрочные проверки отделены от построчных CHECK [11].')

 w.page('3 Функциональная модель',1)
 sub(w,'3.1 Состав и взаимосвязь функций',
 'Завершение обращения требует установить клиента и его счета, обработать выбранную банковскую операцию и выдать документ с проверяемым результатом. Эту работу обеспечивают F1 — ведение клиентского контекста, F2 — обслуживание карт, F3 — учёт и проведение переводов, F4 — ведение кредитных договоров, F5 — предоставление сведений и контроль.',
 'Контекстная DFD Б.1 показывает входящие команды и выдаваемые документы. На Б.2 представлены межфункциональные потоки, на Б.9 — обращения к общим хранилищам. F1 ведёт реквизиты и подтверждённые начальные данные, а денежные изменения текущего учёта выполняет F3. Результаты профильных функций поступают в F5 для представления сотруднику.',
 'Дерево Б.3 раскрывает состав функций до отдельных результатов обработки. DFD Б.4–Б.8 уточняют преобразования и сохраняют границы родительских функций. Поля потоков определены в приложении Б. Повтор кода E или D обозначает того же участника или хранилище; внутренние L-потоки связывают дочерние функции.')
